            if (state.currentPeriod === 1 && d.decisionA) state.domainState.ceoRating = d.decisionA;
            if (state.currentPeriod === 4 && d.decisionA) state.domainState.crisisResponse = d.decisionA;

            if (state.currentPeriod === 4) {
                var wbChoice = state.domainState.whistleblowerChoice;
                if (wbChoice === 'optA') {
                    stockDelta += 5;
                    roundGQI += 3;
                } else if (wbChoice === 'optB' || wbChoice === 'optC') {
                    stockDelta -= 4;
                    roundGQI -= 2;
                } else if (wbChoice === 'optD') {
                    stockDelta -= 10;
                    roundGQI -= 5;
                }
            }

            roundGQI = Math.max(0, Math.min(25, roundGQI));

            state.domainState.gqiScore += roundGQI;
            state.domainState.decisionQualityTotal += decisionQuality;
            state.domainState.processIntegrityTotal += processIntegrity;
            state.domainState.riskOversightTotal += riskOversight;
            state.domainState.stakeholderCommTotal += stakeholderComm;
            state.domainState.stockPrice = Math.round(state.domainState.stockPrice * (1 + stockDelta / 100));

            state.domainState.gqiHistory.push(roundGQI);
            state.domainState.stockHistory.push(state.domainState.stockPrice);

            // overallScore is the running gqiScore, the same totalGQI metric getPerformanceSummary uses for its verdict, already 0-100, clamped
            var overallScore = Math.max(0, Math.min(100, Math.round(state.domainState.gqiScore)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var eventText = this._getOutcomeText(state.currentPeriod, d, scoreA, scoreB, state);
            var eventPanel = document.getElementById('eventPanel');
            var eventTextEl = document.getElementById('eventText');
            if (eventPanel && eventTextEl) {
                eventPanel.style.display = 'block';
                eventTextEl.innerHTML = eventText;
            }

            // Advance the briefing + decision controls to the NEXT round immediately,
            // before the framework increments currentPeriod, using the correct next value.
            // (The previous setTimeout read state.currentPeriod AFTER the engine had already
            //  incremented it, jumping the briefing one round ahead and desyncing scoring.)
            // The Outcome Report is intentionally left visible so the player can read the
            // feedback for the meeting they just completed; it is replaced on the next submit.
            var nextPeriod = (state.currentPeriod || 1) + 1;
            var maxP = state.maxPeriods || this.ROUNDS.length;
            if (nextPeriod <= maxP) {
                this._renderRound(nextPeriod);
            }

            return {
                period: state.currentPeriod,
                decisionA: d.decisionA,
                decisionB: d.decisionB,
                decisionAKey: this._textKey(round.decAOptions, d.decisionA),
                decisionBKey: this._textKey(round.decBOptions, d.decisionB),
                weakCost: weakCost,
                overallScore: overallScore,
                score: overallScore,
                scoreA: scoreA,
                scoreB: scoreB,
                roundGQI: roundGQI,
                cumulativeGQI: state.domainState.gqiScore,
                stockPrice: state.domainState.stockPrice,
                stockDelta: stockDelta
            };
        }

        _textKey(list, value) {
            for (var i = 0; i < list.length; i++) { if (list[i].value === value) return list[i].textKey; }
            return '';
        }

        _tr(key) {
            return window.mySimulation && window.mySimulation.t ? window.mySimulation.t(key) : key;
        }

        _getOutcomeText(period, decisions, scoreA, scoreB, state) {
            var t = window.mySimulation.t.bind(window.mySimulation);
            var avg = (scoreA + scoreB) / 2;
            var key = 'outcome_r' + period + '_';
            if (avg >= 4) key += 'good';
            else if (avg >= 3) key += 'moderate';
            else key += 'poor';
            return t(key);
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('gqiDisplay', 'domainState.gqiScore',
