            uiManager.bind('stockDisplay', 'domainState.stockPrice',
                function(v) { return Math.round(v); });
            uiManager.bind('decisionQualityDisplay', 'domainState.decisionQualityTotal',
                function(v) { return Math.round(v); });
            uiManager.bind('riskDisplay', 'domainState.riskOversightTotal',
                function(v) { return Math.round(v); });
        }

