        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var res = history.map(function(r) { return r.results || {}; });
            var totalGQI = res.reduce(function(sum, r) { return sum + (r.roundGQI || 0); }, 0);
            totalGQI = Math.max(0, Math.min(100, Math.round(totalGQI)));
            var finalStock = res[res.length - 1].stockPrice || 100;
            var tier = this._tier(totalGQI);
            var picks = res.map(function(r) { return { a: r.decisionA, b: r.decisionB }; });
            var dq = 0, pi = 0;
            res.forEach(function(r) {
                dq += Math.round(((r.scoreA || 0) + (r.scoreB || 0)) * 1.5);
                pi += ((r.scoreA || 0) >= 4 ? 3 : 1) + ((r.scoreB || 0) >= 4 ? 3 : 1);
            });
            return {
                totalGQI: totalGQI,
                avgGQI: Math.round((totalGQI / res.length) * 10) / 10,
                finalStockIndex: finalStock,
                performance: tier,
                performanceKey: 'tier_' + tier,
                performanceLabel: this._tr('tier_' + tier),
                composite: totalGQI,
                overallScore: totalGQI,
                totalScore: totalGQI,
                score: totalGQI,
                decisionQualityTotal: dq,
                processIntegrityTotal: pi,
                picks: picks,
                insights: this._insightKeys(picks, res, finalStock).map(this._tr.bind(this))
            };
        }

        _tier(score) {
            if (score >= 90) return 'exemplary';
            if (score >= 75) return 'effective';
            if (score >= 60) return 'adequate';
            return 'needs_improvement';
        }

        _insightKeys(picks, res, finalStock) {
            var k = [];
            var p1 = picks[0] || {}, p4 = picks[3] || {};
            var wb = p1.b;
            if (wb === 'optA') k.push('ins_wb_external');
            else if (wb === 'optB') k.push('ins_wb_internal');
            else if (wb === 'optC') k.push('ins_wb_auditor');
            else if (wb === 'optD') k.push('ins_wb_routine');
            if (p1.a === 'exceeds') k.push('ins_rating_exceeds');
            else if (p1.a === 'below') k.push('ins_rating_below');
            else if (p1.a === 'meets') k.push('ins_rating_meets');
            else if (p1.a === 'partial') k.push('ins_rating_partial');
            if (p4.a === 'minimal') k.push('ins_crisis_minimal');
            else if (p4.a === 'defer_mgmt') k.push('ins_crisis_defer');
            var weak = res.filter(function(r) { return (r.weakCost || 0) >= 4; }).length;
            if (weak >= 2) k.push('ins_weak_meetings');
            if (finalStock < 100) k.push('ins_stock_down');
            return k;
        }

        _turningKey(picks) {
            var wb = (picks[0] || {}).b;
            if (wb === 'optA') return 'turn_external';
            if (wb === 'optD') return 'turn_routine';
            return 'turn_internal';
        }

        formatCompletionMessage(summary) {
            if (!summary || summary.totalGQI === undefined) return '';
            var t = this._tr.bind(this);
            var esc = function(x) { return String(x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
            var picks = summary.picks || [];
            var h = '<div class="governance-sim-cm">';
            h += '<p class="governance-sim-cm-score"><strong>' + summary.totalGQI + ' / 100</strong> — ' + esc(t('tier_' + summary.performance)) + '</p>';
            h += '<ul class="governance-sim-cm-kpis">';
            h += '<li>' + esc(t('gqi_label')) + ': ' + summary.totalGQI + ' / 100</li>';
            h += '<li>' + esc(t('stock_label')) + ': ' + summary.finalStockIndex + '</li>';
            h += '<li>' + esc(t('cm_outcome')) + ': ' + summary.decisionQualityTotal + ' / 60</li>';
            h += '<li>' + esc(t('cm_process')) + ': ' + summary.processIntegrityTotal + ' / 24</li>';
            h += '</ul>';
            h += '<h4>' + esc(t('cm_turning')) + '</h4><p>' + esc(t(this._turningKey(picks))) + '</p>';
            h += '<h4>' + esc(t('cm_insights')) + '</h4><ul>';
            (summary.insights || []).forEach(function(x) { h += '<li>' + esc(x) + '</li>'; });
            h += '</ul><h4>' + esc(t('cm_questions')) + '</h4><ol>';
            ['cm_q1', 'cm_q2', 'cm_q3'].forEach(function(q) { h += '<li>' + esc(t(q)) + '</li>'; });
            h += '</ol></div>';
            return h;
        }

        getHint(state, results) {
            if (!results) return null;
            var avg = ((results.scoreA || 0) + (results.scoreB || 0)) / 2;
            if (avg <= 2) return window.mySimulation.t('hint_poor');
            if (avg <= 3) return window.mySimulation.t('hint_moderate');
            if (avg >= 4.5) return window.mySimulation.t('hint_excellent');
            return null;
        }

